Lemma pbl_C1 : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s pixt : Z),
  frm_zero cs ->
  (4096 + 112 <= s <= 2 ^ 47)%Z ->
  (0 <= pixt < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 112)) 112 = true ->
  getr regs 2 = Z_to_bv 64 (s - 112) ->
  getr regs 10 = Z_to_bv 64 pixt ->
