Lemma pbl_C6 : forall (fx : FPState) regs (m : word -> option byte) (s pixs : Z),
  (4096 + 112 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 112) ->
  getr regs 8 = Z_to_bv 64 pixs ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 185720) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 109464) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 185732 /\ getr regs' 2 = Z_to_bv 64 (s - 112) /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 2 /\
      regs_agree (fun r => In r [1; 10; 11]%list) regs regs').
Proof.
