Lemma pbl_C9 : forall (fx : FPState) regs (m : word -> option byte) (s r g b : Z),
  (4096 + 112 <= s <= 2 ^ 47)%Z ->
  (0 <= r < 2 ^ 64)%Z ->
  (0 <= g < 2 ^ 64)%Z ->
  (0 <= b < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 112) ->
  getr regs 19 = Z_to_bv 64 r ->
  getr regs 20 = Z_to_bv 64 g ->
  getr regs 8 = Z_to_bv 64 b ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 185772) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 113660) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 185788 /\ getr regs' 2 = Z_to_bv 64 (s - 112) /\ getr regs' 10 = Z_to_bv 64 r /\ getr regs' 11 = Z_to_bv 64 g /\ getr regs' 12 = Z_to_bv 64 b /\
      regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs').
Proof.
