Lemma pbl_C10 : forall (fx : FPState) regs (m : word -> option byte) (s pixd : Z),
  (4096 + 112 <= s <= 2 ^ 47)%Z ->
  (0 <= pixd < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 112) ->
  getr regs 10 = Z_to_bv 64 pixd ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 185788) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 103464) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 185800 /\ getr regs' 2 = Z_to_bv 64 (s - 112) /\ getr regs' 8 = Z_to_bv 64 pixd /\ getr regs' 10 = Z_to_bv 64 (s - 96) /\
      regs_agree (fun r => In r [1; 8; 10]%list) regs regs').
