Lemma pbl_C11 : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 112 <= s <= 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 112) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 185800) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 103464) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 185808 /\ getr regs' 2 = Z_to_bv 64 (s - 112) /\ getr regs' 10 = Z_to_bv 64 (s - 104) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
Proof.
